import * as path from 'node:path';
import * as fs from 'node:fs/promises';
import { EventEmitter } from 'node:events';
import type { Config } from '../config/config.js';
// FileScopeService is used by SubtaskRunner
import { SubtaskRunner, type SubtaskResult } from './subtaskRunner.js';
import { getErrorMessage } from '../utils/errors.js';

/**
 * Task plan generated by the planner agent
 */
export interface TaskPlan {
  /** Descriptive title for the overall task */
  title: string;
  /** Individual subtasks to be executed */
  subtasks: Subtask[];
  /** Potential risks identified by the planner */
  risks?: string[];
  /** Additional notes or context */
  notes?: string[];
  /** Estimated duration in minutes */
  estimatedDuration?: number;
}

/**
 * Individual subtask definition
 */
export interface Subtask {
  /** Unique identifier for this subtask */
  id: string;
  /** Clear description of what this subtask should accomplish */
  goal: string;
  /** Suggested agent to use for this subtask */
  suggestedAgent?: string;
  /** File patterns this subtask is allowed to access */
  fileGlobs?: string[];
  /** Specific tools this subtask is allowed to use */
  tools?: string[];
  /** Preferred model for this subtask (for cost optimization) */
  model?: string;
  /** Priority level for execution ordering */
  priority?: 'low' | 'medium' | 'high';
  /** Estimated duration in minutes */
  estimatedDuration?: number;
}

/**
 * Changeset manifest tracking what files were modified
 */
export interface Changeset {
  /** Files that were written or modified */
  touchedFiles: string[];
  /** Human-readable notes about the changes */
  notes?: string[];
  /** Suggested test commands to run after changes */
  testCommands?: string[];
  /** Links to related files or documentation */
  relatedFiles?: string[];
}

/**
 * Execution status of a subtask
 */
export type SubtaskStatus = 
  | 'pending'     // Not yet started
  | 'running'     // Currently executing
  | 'completed'   // Successfully completed
  | 'failed'      // Failed with error
  | 'cancelled';  // Cancelled by user or system

/**
 * Execution context for a subtask
 */
export interface SubtaskExecution {
  /** The subtask definition */
  subtask: Subtask;
  /** Current execution status */
  status: SubtaskStatus;
  /** Start time of execution */
  startTime?: Date;
  /** End time of execution */  
  endTime?: Date;
  /** Error message if failed */
  error?: string;
  /** Result of execution */
  result?: SubtaskResult;
  /** Agent that was used for this subtask */
  agentUsed?: string;
  /** Model that was used for this subtask */
  modelUsed?: string;
}

/**
 * Configuration for plan execution
 */
export interface ExecutionConfig {
  /** Maximum number of subtasks to run in parallel */
  maxParallel?: number;
  /** Base directory for file operations */
  baseDir?: string;
  /** Global file scope restrictions */
  globalFileScope?: string[];
  /** Timeout for individual subtasks in milliseconds */
  subtaskTimeout?: number;
  /** Whether to continue on individual subtask failures */
  continueOnFailure?: boolean;
  /** Model to use for planning */
  plannerModel?: string;
}

/**
 * Complete execution report
 */
export interface ExecutionReport {
  /** The plan that was executed */
  plan: TaskPlan;
  /** Execution details for each subtask */
  executions: SubtaskExecution[];
  /** Overall execution status */
  status: 'completed' | 'partial' | 'failed';
  /** Start time of overall execution */
  startTime: Date;
  /** End time of overall execution */
  endTime: Date;
  /** Total duration in milliseconds */
  duration: number;
  /** Aggregated changeset from all subtasks */
  aggregatedChangeset: Changeset;
  /** Detected conflicts between subtasks */
  conflicts: FileConflict[];
  /** Execution artifacts directory */
  artifactsDir: string;
}

/**
 * File conflict detected between subtasks
 */
export interface FileConflict {
  /** File path that has conflicts */
  filePath: string;
  /** Subtask IDs that touched this file */
  subtaskIds: string[];
  /** Conflict severity */
  severity: 'warning' | 'error';
  /** Human-readable description */
  description: string;
}

/**
 * Planning strategy for task decomposition
 */
export type PlanningStrategy = 
  | 'auto'      // Let planner decide best approach
  | 'files'     // Decompose by file/directory boundaries  
  | 'skills'    // Decompose by required skills/agents
  | 'sequential' // Create sequential dependent tasks
  | 'parallel';  // Create fully parallel independent tasks

/**
 * Core orchestration service for multi-agent task execution
 */
export class Orchestrator extends EventEmitter {
  private readonly config: Config;
  private readonly subtaskRunner: SubtaskRunner;
  private currentExecution?: ExecutionReport;
  
  constructor(config: Config) {
    super();
    this.config = config;
    this.subtaskRunner = new SubtaskRunner(config);
  }

  /**
   * Generate a task plan using the planner agent
   */
  async planTask(
    taskDescription: string,
    options: {
      agentCount: number;
      strategy?: PlanningStrategy;
      hints?: string[];
    }
  ): Promise<TaskPlan> {
    const { agentCount, strategy = 'auto', hints = [] } = options;
    
    // Get available agents for the planner to reference
    const agentLoader = this.config.getAgentLoader();
    const availableAgents = Array.from(agentLoader.loadAgents().keys());
    
    // Build planner prompt
    const plannerPrompt = this.buildPlannerPrompt(
      taskDescription,
      agentCount,
      strategy,
      hints,
      availableAgents
    );

    // Execute planning using a strong model (Claude 4 Sonnet by default)
    const contentGenerator = this.config.getContentGenerator();
    
    // Create a temporary session for planning
    const response = await contentGenerator.generateContent({
      model: 'claude-4-sonnet',
      contents: [
        {
          role: 'user',
          parts: [{ text: plannerPrompt }],
        },
      ],
    }, 'task-planner');

    // Parse the JSON response
    const responseText = response.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!responseText) {
      throw new Error('No response from planner');
    }

    // Extract JSON from markdown code blocks if present
    let jsonText = responseText.trim();
    
    // Look for JSON wrapped in markdown code blocks
    const jsonBlockMatch = jsonText.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (jsonBlockMatch) {
      jsonText = jsonBlockMatch[1].trim();
    }
    
    try {
      // Parse the extracted JSON
      const plan = JSON.parse(jsonText) as TaskPlan;
      
      // Validate the plan structure
      this.validatePlan(plan, agentCount);
      
      return plan;
    } catch (error) {
      throw new Error(`Failed to parse plan: ${getErrorMessage(error)}\n\nExtracted JSON: ${jsonText}\n\nFull Response: ${responseText}`);
    }
  }

  /**
   * Execute a task plan with parallel subtask execution
   */
  async executePlan(
    plan: TaskPlan,
    config: ExecutionConfig = {}
  ): Promise<ExecutionReport> {
    const {
      maxParallel = 3, // Conservative for Bedrock rate limiting
      baseDir = process.cwd(),
      globalFileScope = [],
      subtaskTimeout = 600000, // 10 minutes default
      continueOnFailure = true,
    } = config;

    // Create artifacts directory
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const planId = plan.title.toLowerCase().replace(/[^a-z0-9]/g, '-').slice(0, 30);
    const artifactsDir = path.join(baseDir, '.devx', 'delegate', `${planId}-${timestamp}`);
    await fs.mkdir(artifactsDir, { recursive: true });

    // Initialize execution report
    const startTime = new Date();
    const executions: SubtaskExecution[] = plan.subtasks.map(subtask => ({
      subtask,
      status: 'pending' as SubtaskStatus,
    }));

    this.currentExecution = {
      plan,
      executions,
      status: 'partial',
      startTime,
      endTime: new Date(), // Will be updated when complete
      duration: 0,
      aggregatedChangeset: { touchedFiles: [] },
      conflicts: [],
      artifactsDir,
    };

    // Emit planning complete event
    this.emit('planningComplete', { plan, artifactsDir });

    try {
      // Execute subtasks with concurrency control
      const results = await this.executeSubtasksWithConcurrency(
        plan.subtasks,
        maxParallel,
        {
          baseDir,
          globalFileScope,
          subtaskTimeout,
          continueOnFailure,
          artifactsDir,
        }
      );

      // Update execution report with results
      results.forEach((result, index) => {
        executions[index].result = result.result;
        executions[index].status = result.status;
        executions[index].error = result.error;
        executions[index].agentUsed = result.agentUsed;
        executions[index].modelUsed = result.modelUsed;
        executions[index].startTime = result.startTime;
        executions[index].endTime = result.endTime;
      });

      // Generate final report
      const endTime = new Date();
      const duration = endTime.getTime() - startTime.getTime();
      
      const aggregatedChangeset = this.aggregateChangesets(results);
      const conflicts = this.detectConflicts(results);
      
      const finalStatus = this.determineOverallStatus(executions);

      this.currentExecution = {
        ...this.currentExecution,
        status: finalStatus,
        endTime,
        duration,
        aggregatedChangeset,
        conflicts,
      };

      // Save execution report
      await this.saveExecutionReport(this.currentExecution);

      // Emit completion event
      this.emit('executionComplete', this.currentExecution);

      return this.currentExecution;

    } catch (error) {
      // Update execution report with error
      this.currentExecution.status = 'failed';
      this.currentExecution.endTime = new Date();
      this.currentExecution.duration = this.currentExecution.endTime.getTime() - startTime.getTime();

      // Save partial execution report
      await this.saveExecutionReport(this.currentExecution);

      // Emit error event
      this.emit('executionError', { error: getErrorMessage(error), report: this.currentExecution });

      throw error;
    }
  }

  /**
   * Get the current execution status
   */
  getCurrentExecution(): ExecutionReport | undefined {
    return this.currentExecution;
  }

  /**
   * Build the prompt for the planner agent
   */
  private buildPlannerPrompt(
    taskDescription: string,
    agentCount: number,
    strategy: PlanningStrategy,
    hints: string[],
    availableAgents: string[]
  ): string {
    const systemContext = `You create work plans for software development tasks.

Rules:
- Respond with ONLY valid JSON - no markdown code blocks, no explanations, no prose.
- Produce exactly ${agentCount} subtasks in the JSON format specified below.
- Prefer disjoint fileGlobs per subtask to minimize conflicts.
- If a specialized agent fits the subtask, set suggestedAgent from available agents.
- Keep each subtask focused and achievable (30-90 minutes of work).
- Use strategy "${strategy}" to guide decomposition approach.

Available agents: ${availableAgents.join(', ')}

JSON Schema:
{
  "title": "string",
  "subtasks": [
    {
      "id": "string (short slug)",
      "goal": "string (clear outcome)",
      "suggestedAgent": "string (optional)",
      "fileGlobs": ["string (optional)"],
      "tools": ["string (optional)"],
      "model": "string (optional: claude-3-5-haiku for simple, claude-4-sonnet for complex)",
      "priority": "string (optional: low|medium|high)",
      "estimatedDuration": "number (optional: minutes)"
    }
  ],
  "risks": ["string (optional)"],
  "notes": ["string (optional)"],
  "estimatedDuration": "number (optional: total minutes)"
}`;

    const userPrompt = `Task: "${taskDescription}"
Agent Count: ${agentCount}
Strategy: ${strategy}
${hints.length > 0 ? `Hints: ${hints.join(', ')}` : ''}

Generate a JSON plan following the schema above.`;

    return `${systemContext}\n\n${userPrompt}`;
  }

  /**
   * Validate that a plan meets requirements
   */
  private validatePlan(plan: TaskPlan, expectedCount: number): void {
    if (!plan.title || typeof plan.title !== 'string') {
      throw new Error('Plan must have a string title');
    }

    if (!Array.isArray(plan.subtasks)) {
      throw new Error('Plan must have subtasks array');
    }

    if (plan.subtasks.length !== expectedCount) {
      throw new Error(`Plan must have exactly ${expectedCount} subtasks, got ${plan.subtasks.length}`);
    }

    for (const [index, subtask] of plan.subtasks.entries()) {
      if (!subtask.id || typeof subtask.id !== 'string') {
        throw new Error(`Subtask ${index} must have a string id`);
      }

      if (!subtask.goal || typeof subtask.goal !== 'string') {
        throw new Error(`Subtask ${index} must have a string goal`);
      }

      // Validate optional fields
      if (subtask.fileGlobs && !Array.isArray(subtask.fileGlobs)) {
        throw new Error(`Subtask ${index} fileGlobs must be an array`);
      }

      if (subtask.tools && !Array.isArray(subtask.tools)) {
        throw new Error(`Subtask ${index} tools must be an array`);
      }
    }
  }

  /**
   * Execute subtasks with concurrency control
   */
  private async executeSubtasksWithConcurrency(
    subtasks: Subtask[],
    maxParallel: number,
    options: {
      baseDir: string;
      globalFileScope: string[];
      subtaskTimeout: number;
      continueOnFailure: boolean;
      artifactsDir: string;
    }
  ): Promise<Array<{
    result?: SubtaskResult;
    status: SubtaskStatus;
    error?: string;
    agentUsed?: string;
    modelUsed?: string;
    startTime?: Date;
    endTime?: Date;
  }>> {
    // Simple concurrency control without external dependencies
    const results: Array<{
      result?: SubtaskResult;
      status: SubtaskStatus;
      error?: string;
      agentUsed?: string;
      modelUsed?: string;
      startTime?: Date;
      endTime?: Date;
    }> = new Array(subtasks.length);

    const executeSubtask = async (index: number): Promise<void> => {
      const subtask = subtasks[index];
      const startTime = new Date();
      
      try {
        this.emit('subtaskStarted', { subtask, index });
        
        const result = await this.subtaskRunner.runSubtask(subtask, {
          baseDir: options.baseDir,
          globalFileScope: options.globalFileScope,
          timeout: options.subtaskTimeout,
          artifactsDir: options.artifactsDir,
        });

        const endTime = new Date();
        results[index] = {
          result,
          status: 'completed',
          agentUsed: result.agentUsed,
          modelUsed: result.modelUsed,
          startTime,
          endTime,
        };

        this.emit('subtaskCompleted', { subtask, index, result });

      } catch (error) {
        const endTime = new Date();
        const errorMessage = getErrorMessage(error);
        
        results[index] = {
          status: 'failed',
          error: errorMessage,
          startTime,
          endTime,
        };

        this.emit('subtaskFailed', { subtask, index, error: errorMessage });

        if (!options.continueOnFailure) {
          throw error;
        }
      }
    };

    // Execute with simple concurrency control
    const executing = new Set<Promise<void>>();
    let nextIndex = 0;

    while (nextIndex < subtasks.length || executing.size > 0) {
      // Start new tasks up to maxParallel
      while (executing.size < maxParallel && nextIndex < subtasks.length) {
        const task = executeSubtask(nextIndex);
        executing.add(task);
        nextIndex++;

        // Remove from executing set when done
        task.finally(() => executing.delete(task));
      }

      // Wait for at least one task to complete
      if (executing.size > 0) {
        await Promise.race(executing);
      }
    }

    return results;
  }

  /**
   * Aggregate changesets from all subtask results
   */
  private aggregateChangesets(results: Array<{ result?: SubtaskResult }>): Changeset {
    const allTouchedFiles = new Set<string>();
    const allNotes: string[] = [];
    const allTestCommands: string[] = [];
    const allRelatedFiles = new Set<string>();

    for (const { result } of results) {
      if (result?.changeset) {
        result.changeset.touchedFiles.forEach(file => allTouchedFiles.add(file));
        if (result.changeset.notes) {
          allNotes.push(...result.changeset.notes);
        }
        if (result.changeset.testCommands) {
          allTestCommands.push(...result.changeset.testCommands);
        }
        if (result.changeset.relatedFiles) {
          result.changeset.relatedFiles.forEach(file => allRelatedFiles.add(file));
        }
      }
    }

    return {
      touchedFiles: Array.from(allTouchedFiles),
      notes: allNotes.length > 0 ? allNotes : undefined,
      testCommands: allTestCommands.length > 0 ? Array.from(new Set(allTestCommands)) : undefined,
      relatedFiles: allRelatedFiles.size > 0 ? Array.from(allRelatedFiles) : undefined,
    };
  }

  /**
   * Detect file conflicts between subtasks
   */
  private detectConflicts(results: Array<{ result?: SubtaskResult }>): FileConflict[] {
    const fileToSubtasks = new Map<string, string[]>();

    // Map files to subtasks that touched them
    results.forEach(({ result }, index) => {
      if (result?.changeset) {
        result.changeset.touchedFiles.forEach(file => {
          if (!fileToSubtasks.has(file)) {
            fileToSubtasks.set(file, []);
          }
          fileToSubtasks.get(file)!.push(result.subtaskId);
        });
      }
    });

    // Find conflicts (files touched by multiple subtasks)
    const conflicts: FileConflict[] = [];
    for (const [filePath, subtaskIds] of fileToSubtasks) {
      if (subtaskIds.length > 1) {
        conflicts.push({
          filePath,
          subtaskIds,
          severity: 'warning', // Could be upgraded based on analysis
          description: `File modified by multiple subtasks: ${subtaskIds.join(', ')}`,
        });
      }
    }

    return conflicts;
  }

  /**
   * Determine overall execution status
   */
  private determineOverallStatus(executions: SubtaskExecution[]): 'completed' | 'partial' | 'failed' {
    const statusCounts = executions.reduce((counts, exec) => {
      counts[exec.status] = (counts[exec.status] || 0) + 1;
      return counts;
    }, {} as Record<SubtaskStatus, number>);

    if (statusCounts.failed === executions.length) {
      return 'failed';
    } else if (statusCounts.completed === executions.length) {
      return 'completed';
    } else {
      return 'partial';
    }
  }

  /**
   * Save execution report to artifacts directory
   */
  private async saveExecutionReport(report: ExecutionReport): Promise<void> {
    const reportPath = path.join(report.artifactsDir, 'execution-report.json');
    await fs.writeFile(reportPath, JSON.stringify(report, null, 2));

    // Also save a human-readable summary
    const summaryPath = path.join(report.artifactsDir, 'summary.md');
    const summary = this.generateSummaryMarkdown(report);
    await fs.writeFile(summaryPath, summary);
  }

  /**
   * Generate human-readable summary in Markdown format
   */
  private generateSummaryMarkdown(report: ExecutionReport): string {
    const { plan, executions, status, duration, aggregatedChangeset, conflicts } = report;
    
    const durationMinutes = Math.round(duration / 60000);
    const completedCount = executions.filter(e => e.status === 'completed').length;
    
    let markdown = `# Delegation Execution Report

## Overview
- **Task**: ${plan.title}
- **Status**: ${status.toUpperCase()}
- **Duration**: ${durationMinutes} minutes
- **Completed**: ${completedCount}/${executions.length} subtasks
- **Files Modified**: ${aggregatedChangeset.touchedFiles.length}

## Subtask Results
`;

    executions.forEach((exec, index) => {
      const duration = exec.startTime && exec.endTime 
        ? Math.round((exec.endTime.getTime() - exec.startTime.getTime()) / 60000)
        : 0;
      
      markdown += `
### ${index + 1}. ${exec.subtask.goal}
- **Status**: ${exec.status}
- **Agent**: ${exec.agentUsed || 'default'}
- **Duration**: ${duration} minutes
${exec.error ? `- **Error**: ${exec.error}` : ''}
${exec.result?.changeset?.touchedFiles.length ? `- **Files**: ${exec.result.changeset.touchedFiles.join(', ')}` : ''}
`;
    });

    if (conflicts.length > 0) {
      markdown += `
## Conflicts Detected
`;
      conflicts.forEach(conflict => {
        markdown += `- **${conflict.filePath}**: Modified by subtasks ${conflict.subtaskIds.join(', ')}\n`;
      });
    }

    if (aggregatedChangeset.testCommands && aggregatedChangeset.testCommands.length > 0) {
      markdown += `
## Suggested Test Commands
${aggregatedChangeset.testCommands.map(cmd => `- \`${cmd}\``).join('\n')}
`;
    }

    return markdown;
  }
}